def discount_cents(subtotal_cents, percent):
    return subtotal_cents * percent // 100


def checkout_total(subtotal_cents, discount_percent, tax_percent):
    discounted = subtotal_cents - discount_cents(subtotal_cents, discount_percent)
    tax = discounted * tax_percent // 100
    return discounted + tax

